mapper.select:
select workorderCode,lastProcessId,lastProcessCode,lastProcessName,lastUserId,lastUserName,lastNickName,lastReportingTime
from (
    select r.workorder_code workorderCode,r.process_id lastProcessId,r.process_code lastProcessCode,
           r.process_name lastProcessName,r.user_id lastUserId,r.user_name lastUserName,r.nick_name lastNickName,
           r.create_time lastReportingTime,
           row_number() over(partition by r.workorder_code order by r.create_time desc,r.record_id desc) rn
    from pro_reporting_work r where r.workorder_code in
    #{code}
) latest where rn=1

select r.record_id recordId,r.create_time createTime,r.xtransfer_no xtransferNo,r.route_id routeId,
       r.route_name routeName,r.process_id processId,r.process_code processCode,r.process_name processName,
       r.unit_of_measure unitOfMeasure,r.user_id userId,r.user_name userName,r.nick_name nickName,
       r.reporting_work_quantity reportingWorkQuantity,r.status
from pro_reporting_work r where r.workorder_code=#{query.workorderCode}
and r.xtransfer_no=#{query.xtransferNo}
and r.route_id=#{query.routeId}
and r.process_id=#{query.processId}
and r.process_code=#{query.processCode}
order by r.create_time desc,r.record_id desc
